enum Node { Br(Vec<Rc<Node>>), Lf(Vec<i32>) }
#[derive(Clone)]
struct V { size: usize, shift: u32, root: Rc<Node>, tail: Rc<Vec<i32>> }
impl V {
    fn new() -> V { V{size:0, shift:5, root:Rc::new(Node::Br(Vec::new())), tail:Rc::new(Vec::new())} }
    fn tail_off(&self) -> usize { self.size - self.tail.len() }
    fn get(&self, i: usize) -> Option<&i32> {
        if i >= self.size { return None; }
        let to = self.tail_off();
        if i >= to { return self.tail.get(i - to); }
        let mut n: &Node = &self.root;
        let mut level = self.shift;
        while level > 0 {
            match n { Node::Br(c) => { n = &c[(i >> level) & 31]; }, Node::Lf(_) => return None }
            level -= 5;
        }
        match n { Node::Lf(v) => v.get(i & 31), _ => None }
    }
    fn push_back(&self, x: i32) -> V {
        if self.tail.len() < 32 {
            let mut t = Vec::with_capacity(32);
            t.extend_from_slice(&self.tail); t.push(x);
            return V{size:self.size+1, shift:self.shift, root:Rc::clone(&self.root), tail:Rc::new(t)};
        }
        let leaf = Rc::new(Node::Lf((*self.tail).clone()));
        let trie_len = self.tail_off();
        let cap = 1usize << (self.shift + 5);
        let (root, shift) = if trie_len == cap {
            (Rc::new(Node::Br(vec![Rc::clone(&self.root), new_path(self.shift, leaf)])), self.shift+5)
        } else {
            (push_leaf(&self.root, self.shift, trie_len, leaf), self.shift)
        };
        let mut t = Vec::with_capacity(32); t.push(x);
        V{size:self.size+1, shift, root, tail:Rc::new(t)}
    }
    fn push_back_mut(&mut self, x: i32) {
        if self.tail.len() < 32 {
            let t = Rc::make_mut(&mut self.tail);
            t.reserve_exact(32 - t.len());
            t.push(x); self.size += 1; return;
        }
        let leaf = Rc::new(Node::Lf((*self.tail).clone()));
        let trie_len = self.tail_off();
        let cap = 1usize << (self.shift + 5);
        if trie_len == cap {
            let old = std::mem::replace(&mut self.root, Rc::new(Node::Br(Vec::new())));
            self.root = Rc::new(Node::Br(vec![old, new_path(self.shift, leaf)]));
            self.shift += 5;
        } else {
            push_leaf_mut(&mut self.root, self.shift, trie_len, leaf);
        }
        let mut t = Vec::with_capacity(32); t.push(x);
        self.tail = Rc::new(t); self.size += 1;
    }
}
fn new_path(level: u32, leaf: Rc<Node>) -> Rc<Node> {
    if level == 0 { leaf } else { Rc::new(Node::Br(vec![new_path(level-5, leaf)])) }
}
fn push_leaf(node: &Rc<Node>, level: u32, trie_len: usize, leaf: Rc<Node>) -> Rc<Node> {
    let idx = (trie_len >> level) & 31;
    match &**node {
        Node::Br(ch) => {
            let mut ch2 = ch.clone();
            if level == 5 { ch2.push(leaf); }
            else if idx < ch2.len() { ch2[idx] = push_leaf(&ch2[idx], level-5, trie_len, leaf); }
            else { ch2.push(new_path(level-5, leaf)); }
            Rc::new(Node::Br(ch2))
        }
        Node::Lf(_) => unreachable!(),
    }
}
fn push_leaf_mut(node: &mut Rc<Node>, level: u32, trie_len: usize, leaf: Rc<Node>) {
    let idx = (trie_len >> level) & 31;
    match Rc::make_mut(node) {
        Node::Br(ch) => {
            if level == 5 { ch.push(leaf); }
            else if idx < ch.len() { push_leaf_mut(&mut ch[idx], level-5, trie_len, leaf); }
            else { ch.push(new_path(level-5, leaf)); }
        }
        Node::Lf(_) => unreachable!(),
    }
}
