#![allow(dead_code)]
use std::rc::Rc;
const BITS: u32 = 5;
const WIDTH: usize = 1 << BITS;
const MASK: usize = WIDTH - 1;

#[derive(Clone)]
enum Node<T> { Branch(Vec<Rc<Node<T>>>), Leaf(Vec<T>) }

pub struct Vector<T> { size: usize, shift: u32, root: Rc<Node<T>>, tail: Rc<Vec<T>> }

impl<T> Clone for Vector<T> {                       // O(1), no T: Clone bound
    fn clone(&self) -> Self {
        Vector { size: self.size, shift: self.shift,
                 root: Rc::clone(&self.root), tail: Rc::clone(&self.tail) }
    }
}
impl<T> Default for Vector<T> { fn default() -> Self { Vector::new() } }

impl<T> Vector<T> {
    pub fn new() -> Self {
        Vector { size: 0, shift: BITS, root: Rc::new(Node::Branch(Vec::new())), tail: Rc::new(Vec::new()) }
    }
    pub fn len(&self) -> usize { self.size }
    pub fn size(&self) -> usize { self.size }
    pub fn is_empty(&self) -> bool { self.size == 0 }
    fn tail_off(&self) -> usize { self.size - self.tail.len() }
    fn leaf_for(&self, i: usize) -> &[T] {
        let to = self.tail_off();
        if i >= to { return &self.tail; }
        let mut node: &Node<T> = &self.root;
        let mut level = self.shift;
        while level > 0 {
            match node {
                Node::Branch(ch) => { node = &ch[(i >> level) & MASK]; }
                Node::Leaf(_) => break,
            }
            level -= BITS;
        }
        match node { Node::Leaf(v) => v, Node::Branch(_) => &[] }
    }
    pub fn get(&self, i: usize) -> Option<&T> {
        if i >= self.size { return None; }
        self.leaf_for(i).get(i & MASK)
    }
    pub fn first(&self) -> Option<&T> { self.get(0) }
    pub fn last(&self) -> Option<&T> { if self.size == 0 { None } else { self.get(self.size - 1) } }
    pub fn iter(&self) -> Iter<T> { Iter { vec: self, idx: 0, leaf: &[], leaf_base: usize::MAX } }
}

impl<T: Clone> Vector<T> {
    pub fn push_back(&self, x: T) -> Self { let mut v = self.clone(); v.push_back_mut(x); v }
    pub fn push_back_mut(&mut self, x: T) {
        if self.tail.len() < WIDTH {
            let t = Rc::make_mut(&mut self.tail);
            if t.capacity() < WIDTH { t.reserve_exact(WIDTH - t.len()); }
            t.push(x); self.size += 1; return;
        }
        let leaf = Rc::new(Node::Leaf((*self.tail).clone()));
        let trie_len = self.tail_off();
        if (trie_len >> self.shift) >= WIDTH {          // overflow-safe root check
            let old = std::mem::replace(&mut self.root, Rc::new(Node::Branch(Vec::new())));
            let np = new_path(self.shift, leaf);
            self.root = Rc::new(Node::Branch(vec![old, np]));
            self.shift += BITS;
        } else {
            push_leaf_mut(&mut self.root, self.shift, trie_len, leaf);
        }
        let mut t = Vec::with_capacity(WIDTH); t.push(x);
        self.tail = Rc::new(t); self.size += 1;
    }
    pub fn try_update(&self, i: usize, x: T) -> Option<Self> {
        if i >= self.size { return None; }
        let mut v = self.clone();
        if i >= v.tail_off() { Rc::make_mut(&mut v.tail)[i & MASK] = x; }
        else { set_in(&mut v.root, v.shift, i, x); }
        Some(v)
    }
    pub fn update(&self, i: usize, x: T) -> Self {
        match self.try_update(i, x) {
            Some(v) => v,
            None => panic!("Vector::update index out of bounds: len is {} but index is {}", self.size, i),
        }
    }
}
fn new_path<T>(level: u32, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
    if level == 0 { leaf } else { Rc::new(Node::Branch(vec![new_path(level - BITS, leaf)])) }
}
fn push_leaf_mut<T: Clone>(node: &mut Rc<Node<T>>, level: u32, trie_len: usize, leaf: Rc<Node<T>>) {
    let idx = (trie_len >> level) & MASK;
    match Rc::make_mut(node) {
        Node::Branch(ch) => {
            debug_assert!(idx <= ch.len(), "left-dense invariant violated");
            if level == BITS { ch.push(leaf); }
            else if idx < ch.len() { push_leaf_mut(&mut ch[idx], level - BITS, trie_len, leaf); }
            else { ch.push(new_path(level - BITS, leaf)); }
        }
        Node::Leaf(_) => debug_assert!(false, "leaf at branch level"),
    }
}
fn set_in<T: Clone>(node: &mut Rc<Node<T>>, level: u32, i: usize, x: T) {
    match Rc::make_mut(node) {
        Node::Branch(ch) => { let k = (i >> level) & MASK; set_in(&mut ch[k], level - BITS, i, x); }
        Node::Leaf(v) => { v[i & MASK] = x; }
    }
}

pub struct Iter<'a, T> { vec: &'a Vector<T>, idx: usize, leaf: &'a [T], leaf_base: usize }
impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;
    fn next(&mut self) -> Option<&'a T> {
        if self.idx >= self.vec.size { return None; }
        if self.leaf_base != (self.idx & !MASK) {
            self.leaf_base = self.idx & !MASK;
            self.leaf = self.vec.leaf_for(self.idx);
        }
        let out = self.leaf.get(self.idx - self.leaf_base);
        self.idx += 1;
        out
    }
    fn size_hint(&self) -> (usize, Option<usize>) { let n = self.vec.size - self.idx; (n, Some(n)) }
}
impl<'a, T> ExactSizeIterator for Iter<'a, T> {}
impl<'a, T> IntoIterator for &'a Vector<T> {
    type Item = &'a T; type IntoIter = Iter<'a, T>;
    fn into_iter(self) -> Iter<'a, T> { self.iter() }
}
impl<T> std::ops::Index<usize> for Vector<T> {
    type Output = T;
    fn index(&self, i: usize) -> &T {
        match self.get(i) {
            Some(r) => r,
            None => panic!("index out of bounds: the len is {} but the index is {}", self.size, i),
        }
    }
}
impl<T: Clone> std::iter::FromIterator<T> for Vector<T> {
    fn from_iter<I: IntoIterator<Item = T>>(it: I) -> Self {
        let mut v = Vector::new();
        for x in it { v.push_back_mut(x); }
        v
    }
}
impl<T: Clone> Extend<T> for Vector<T> {
    fn extend<I: IntoIterator<Item = T>>(&mut self, it: I) { for x in it { self.push_back_mut(x); } }
}
impl<T: std::fmt::Debug> std::fmt::Debug for Vector<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result { f.debug_list().entries(self.iter()).finish() }
}
impl<T: PartialEq> PartialEq for Vector<T> {
    fn eq(&self, o: &Self) -> bool {
        if self.size != o.size { return false; }
        let mut b = o.iter();
        for x in self.iter() { match b.next() { Some(y) if x == y => {}, _ => return false } }
        true
    }
}
impl<T: Eq> Eq for Vector<T> {}

fn main() {
    // structural-sharing + boundary torture test
    for n in [0usize,1,31,32,33,1023,1024,1025,32767,32768,32769,1048575,1048576,1048577] {
        let mut v: Vector<usize> = Vector::new();
        let mut snaps: Vec<Vector<usize>> = Vec::new();
        for i in 0..n {
            v = v.push_back(i);                        // pure path
            if i % 97 == 0 { snaps.push(v.clone()); }  // O(1) clone, keep history alive
        }
        assert_eq!(v.len(), n);
        // index vs iter agreement
        let mut k = 0usize;
        for (j, x) in v.iter().enumerate() { assert_eq!(*x, j); assert_eq!(v[j], j); k += 1; }
        assert_eq!(k, n);
        assert_eq!(v.get(n), None);
        assert_eq!(v.iter().len(), n);
        // old snapshots unchanged (persistence)
        for s in &snaps { for (j, x) in s.iter().enumerate() { assert_eq!(*x, j); } }
        // update does not mutate the original
        if n > 0 {
            let w = v.update(n/2, 999999);
            assert_eq!(w[n/2], 999999);
            assert_eq!(v[n/2], n/2);
            assert_eq!(w.len(), n);
            assert!(v.try_update(n, 0).is_none());
        }
        let c: Vector<usize> = (0..n).collect();
        assert!(c == v || n == 0 && c.is_empty());
    }
    println!("{:?}", (0..5).collect::<Vector<i32>>());
    println!("ALL_OK");
